import{_ as t,o as a,c as n,a4 as i}from"./chunks/framework.CzJ_HCFe.js";const p=JSON.parse('{"title":"Selected-engine candidate-minute data: producer stage","description":"","frontmatter":{},"headers":[],"relativePath":"decisions/0007-selected-engine-candidate-minutes.md","filePath":"decisions/0007-selected-engine-candidate-minutes.md","lastUpdated":1789991296000}'),s={name:"decisions/0007-selected-engine-candidate-minutes.md"};function r(o,e,d,c,l,u){return a(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="selected-engine-candidate-minute-data-producer-stage" tabindex="-1">Selected-engine candidate-minute data: producer stage <a class="header-anchor" href="#selected-engine-candidate-minute-data-producer-stage" aria-label="Permalink to &quot;Selected-engine candidate-minute data: producer stage&quot;">​</a></h1><h2 id="decision-182" tabindex="-1">Decision (#182) <a class="header-anchor" href="#decision-182" aria-label="Permalink to &quot;Decision (#182)&quot;">​</a></h2><p>Generate a static table of selected-engine facts for <strong>every UTC minute</strong> in the feed window, then losslessly run-length encode consecutive identical values. The producer queries the existing public <code>PanchangamEngine.facts_at</code> owner for Nakshatra, Tithi, Yoga, Karana and lunar Rashi. The existing additive <code>personal.homa.solar_nakshatra_at</code> supplies the selected-engine solar Nakshatra. No frozen engine is modified and no new astronomical formula is introduced.</p><p>The six facts are geocentric in the current engines, so one table serves all cities. The placeholder location and Vaaram supplied during generation do not enter these six outputs; consumer-day Vaaram and special Yogas will be handled by the later browser adapter. Tests compare public results from Hyderabad and New York for every minute of two explicit dates and three reproducibly sampled dates across the 550-day horizon for all three engines.</p><h2 id="discrete-contract" tabindex="-1">Discrete contract <a class="header-anchor" href="#discrete-contract" aria-label="Permalink to &quot;Discrete contract&quot;">​</a></h2><p>The table represents <code>[startMinute, endMinute)</code> in integer Unix UTC minutes. Every represented minute is evaluated. Rows contain the offset from the start and the six names in the declared <code>fields</code> order; a row applies until the next row. <code>schemaVersion: 1</code>, <code>stepSeconds: 60</code>, and the Python system identity are explicit. Bounds must be aware whole-minute instants; accepted non-UTC bounds are normalized to UTC before stepping, including across DST folds/gaps.</p><p>This is not a sparse transition solver or interpolation of continuous event instants. In particular, the model&#39;s Vakya discontinuity at 2027-08-05 18:56:55 UTC is handled by independently querying both adjacent candidate minutes. Tests protect those minutes. Subminute queries are outside the proposed browser contract and must be rejected, never rounded. Evidence limitations of the selected engine remain unchanged, including provisional Vakya historical calibration. Fixtures prove engine consumption parity, not independent ephemeris accuracy.</p><h2 id="generation-delivery-and-staged-activation" tabindex="-1">Generation, delivery and staged activation <a class="header-anchor" href="#generation-delivery-and-staged-activation" aria-label="Permalink to &quot;Generation, delivery and staged activation&quot;">​</a></h2><p>Generation writes one <code>&lt;system&gt;.slot-facts-v1.json</code> before each system&#39;s city loop. The range extends from UTC midnight one day before the first feed date through two days after the last date. Existing city feeds and ICS bytes remain unchanged. The existing landing-build copier stages the new suffix. Workflows, security settings and CNAME remain unchanged.</p><p>This PR is producer-only: the browser continues its existing behavior. After it merges, run the existing <code>generate.yml</code> workflow on master and verify all three hosted tables, their identities/ranges and unchanged existing feed retention. Only then may the separate browser-consumer PR be published. The producer alone does not complete #182.</p><p>A local 550-day measurement evaluated 792,000 minutes for each system, including solar Nakshatra. Drik took 28.67s, Surya Siddhanta 7.33s and Vakya 7.24s; combined output was 581,885 bytes raw and 65,720 bytes gzip. Each table has about 2,465 rows. These are measured local costs, not a CI guarantee. There is no per-city multiplier. The later consumer can reuse one selected-system table and existing browser HTTP caching; uncached offline use must fail clearly instead of substituting approximate facts. Existing chart-screening frame disclosures remain unchanged.</p>',11)])])}const m=t(s,[["render",r]]);export{p as __pageData,m as default};
